<?php
use App\Models\Media;use App\Models\Setting;
$name=(string)($company?->getAttribute('trade_name')?:config('app.name','Votre artisan'));$agencyCity=(string)($company?->getAttribute('city')??'');$department=(string)($company?->getAttribute('department')??'');$region=(string)($company?->getAttribute('region')??'');$radius=(int)($company?->getAttribute('service_radius_km')??0);$copy=$copy??[];
$cities=array_values(array_filter(array_map('trim',preg_split('/[,;\n]/',(string)($copy['zone_cities']??''))?:[])));if(!$cities&&$agencyCity!=='')$cities[]=$agencyCity;
$zoneId=(int)(Setting::first(['key'=>'content.home_zone_media_id'])?->getAttribute('value')??0);$zoneImage=$zoneId?Media::find($zoneId)?->getAttribute('url'):null;
?>
<section class="zone-card editorial-zone"><div class="zone-card-inner"><div class="zone-card-copy"><span class="ph-eyebrow"><?= e($copy['zone_eyebrow']??'Zone d’intervention') ?></span><h2><?= e($copy['zone_title']??($name.' intervient chez vous')) ?></h2><p class="zone-card-text"><?= e($copy['zone_text']??'Contactez-nous pour vérifier notre disponibilité dans votre commune.') ?><?= $radius>0?' Nous nous déplaçons dans un rayon d’environ '.e($radius).' km.':'' ?></p><?php if($cities): ?><div class="zone-card-pills"><?php foreach($cities as $city): ?><span class="zone-pill"><?= e($city) ?></span><?php endforeach; ?></div><?php endif; ?><a class="zone-card-cta" href="#devis">Vérifier votre commune →</a></div><div class="zone-card-map" aria-label="Carte de la zone d’intervention"><?php if($zoneImage): ?><img src="<?= e($zoneImage) ?>" alt="Carte de la zone d’intervention de <?= e($name) ?>" loading="lazy"><?php else: ?><div class="department-fallback"><strong><?= e($department?:$region?:'Votre secteur') ?></strong><span><?= e($agencyCity) ?></span></div><?php endif; ?></div></div></section>
